"""Карты, нарисованные вручную. Ничего не генерируется случайно.

data/maps.json      — порядок карт ("order"), общая легенда символов, общие настройки.
data/maps/<id>.json — одна карта: сетка произвольного размера ("rows"), фон, своя легенда, мобы, награда,
                      "pos": [x, y] — координата карты в СЕТКЕ МИРА (x вправо, y вниз), по ней работают выходы left/right/up/down.
Файлы, имя которых начинается с "_", игра не читает (например, _template.json — заготовка).

Каждый символ сетки — это клетка. Что значит символ, говорит легенда: общая (maps.json) + своя у карты (перекрывает).
Запись легенды — строка-тип ("wall") или словарь:
  type    — физика клетки: empty | wall | platform | ladder | spikes
  exit    — клетка-выход: "next" | "prev" (порядок order) | "back" (откуда пришёл) | id карты |
            "left" | "right" | "up" | "down" (соседняя карта по сетке мира, см. pos) | [x, y] (карта в этой клетке сетки)
  arrive  — (у выхода) символ, у которого появиться на целевой карте
  player  — true: точка старта игрока
  mob     — id моба из mobs.json или "random"\n  boss    — true: точка появления обычного босса (B) или Моргарта (C; boss_type=morgart)
  item    — id оружия или "random": оружие лежит на полу
  sprite  — картинка клетки из assets (иначе стандартная отрисовка типа), draw [w, h], offset [x, y], color [r, g, b]
  damage  — урон шипов
  light   — блок света: "torch" | "lantern" | "crystal" | "orb" или свой словарь (подробно — lighting.py)
decor (список в файле карты, не легенда) — мелкие детали с пиксельной точностью, чисто картинки без физики:
  {"sprite": "environment/wall_1.png", "x": 330, "y": 478, "w": 12, "h": 12, "flip": true, "z": "back"}
  x, y — левый верхний угол в пикселях карты (клетка = 32 px); w, h — размер (по умолчанию 32); flip — отразить;
  z — "back": под клетками карты, иначе поверх. Ставятся в редакторе карт (панель «Мелкие детали», decor_panel.py).
Ящики и сундуки — не символы легенды, а список "containers" в файле карты (ставятся в редакторе, см. containers.py).
"""
import math, random
import pygame as pg
from core import CFG, T, COLS, ROWS, MW
from anim import sprite, image
import weapon
import lighting
import containers
from mob import Mob, spawn_boss

END = "__end__"
PHYS = {"empty": ".", "wall": "#", "platform": "=", "ladder": "H", "spikes": "x"}
VH = ROWS * T   # высота игрового поля в пикселях
BACK = "__back__"
DIRS = {"left": (-1, 0), "right": (1, 0), "up": (0, -1), "down": (0, 1)}
NAMES = {"left": "влево", "right": "вправо", "up": "вверх", "down": "вниз"}

def order(): return [m for m in CFG["maps"].get("order", []) if m in CFG["map_defs"]]

# ---------- сетка мира ----------
def pos_of(mid):
    """Координата карты в сетке мира (поле pos = [x, y]) или None."""
    p = CFG["map_defs"].get(mid, {}).get("pos")
    ok = isinstance(p, (list, tuple)) and len(p) == 2 and all(isinstance(v, int) and not isinstance(v, bool) for v in p)
    return (p[0], p[1]) if ok else None

def map_at(pos):
    """id карты, стоящей в клетке сетки pos, или None."""
    pos = tuple(pos)
    for mid in CFG["map_defs"]:
        if pos_of(mid) == pos: return mid
    return None

def valid_exit(ex, defs):
    if isinstance(ex, (list, tuple)): return len(ex) == 2
    return isinstance(ex, str) and (ex in ("next", "prev", "back", END) or ex in DIRS or ex in defs)

def target_of(cur, target):
    """Куда ведёт выход карты cur: id карты, END (конец), BACK (туда, откуда пришёл) или None (некуда)."""
    if isinstance(target, (list, tuple)): return map_at(target) if len(target) == 2 else None
    o = order()
    if target == "next":
        if cur not in o: return None
        i = o.index(cur) + 1; return o[i] if i < len(o) else END
    if target == "prev":
        if cur not in o: return None
        i = o.index(cur) - 1; return o[i] if i >= 0 else None
    if target == "back": return BACK
    if target == END: return END
    if isinstance(target, str) and target in DIRS:
        p = pos_of(cur)
        return map_at((p[0] + DIRS[target][0], p[1] + DIRS[target][1])) if p else None
    return target if isinstance(target, str) and target in CFG["map_defs"] else None

def used_exits(mid):
    """[(символ, значение exit)] у карты — только символы, которые реально нарисованы в сетке."""
    md = CFG["map_defs"][mid]; lg = legend_of(md); out = []
    for ch in sorted({c for row in md.get("rows", []) for c in row}):
        ex = lg.get(ch, {}).get("exit")
        if ex is not None: out.append((ch, ex))
    return out

def world_links():
    """Реальные переходы: множество пар (откуда, куда). 'back' зависит от прохождения и не учитывается."""
    out = set()
    for mid in CFG["map_defs"]:
        for ch, ex in used_exits(mid):
            t = target_of(mid, ex) if valid_exit(ex, CFG["map_defs"]) else None
            if t and t not in (END, BACK): out.add((mid, t))
    return out

def two_way(a, b):
    """Переход a→b двусторонний: на b есть выход обратно на a или выход 'back'."""
    return (b, a) in world_links() or any(target_of(b, ex) == BACK for _, ex in used_exits(b))

def world_text():
    """Сетка мира текстом (в консоль при запуске и F5)."""
    cells = {m: pos_of(m) for m in CFG["map_defs"] if pos_of(m)}
    if not cells: return "[сетка мира] ни у одной карты нет pos — впиши \"pos\": [x, y] в data/maps/<id>.json"
    xs, ys = [p[0] for p in cells.values()], [p[1] for p in cells.values()]; w = 15
    lines = ["[сетка мира]  x вправо, y вниз", "      " + "".join(f"x={x}".ljust(w) for x in range(min(xs), max(xs) + 1))]
    for y in range(min(ys), max(ys) + 1):
        row = f"y={y}".ljust(6)
        for x in range(min(xs), max(xs) + 1):
            m = map_at((x, y)); row += (f"[{m}]"[:w - 1] if m else "·").ljust(w)
        lines.append(row.rstrip())
    nop = [m for m in CFG["map_defs"] if m not in cells]
    if nop: lines.append("без pos: " + ", ".join(nop))
    return "\n".join(lines)

def norm(v):
    """Запись легенды -> словарь с полем type."""
    v = {"type": v} if isinstance(v, str) else dict(v)
    v.setdefault("type", "empty")
    return v

def legend_of(md):
    lg = {k: norm(v) for k, v in CFG["maps"].get("legend", {}).items()}
    lg.update({k: norm(v) for k, v in md.get("legend", {}).items()})
    return lg

def opt(md, key, default=None):
    """Настройка карты, если нет — из общих настроек maps.json."""
    return md.get(key, CFG["maps"].get(key, default))

class Drop:
    """Оружие на полу."""
    def __init__(s, x, y, wid): s.x, s.y, s.wid = x, y, wid
    def draw(s, v):
        bob = math.sin(pg.time.get_ticks() / 300) * 3
        if s.wid in CFG["weapons"]: ok = weapon.icon(v, s.wid, s.x, s.y - 12 + bob, 36, 30)
        else:   # предмет не-оружие (assets/inventory.json -> items)
            import inventory; ok = inventory.floor_icon(v, s.wid, s.x, s.y - 12 + bob, 32)
        if not ok:
            pg.draw.polygon(v, (255, 220, 90), [(s.x, s.y - 8), (s.x + 8, s.y), (s.x, s.y + 8), (s.x - 8, s.y)])

def random_weapon():
    """Случайное оружие из тех, что разрешены текущему персонажу (allowed_weapons в data/characters.json)."""
    allowed = CFG.get("character", {}).get("allowed_weapons")
    if allowed == []: return None   # пустой список — герою без оружия (маг/инженер) ничего не выпадает
    pool = [w for w in CFG["weapons"] if not allowed or w in allowed]
    return random.choice(pool or list(CFG["weapons"]))

class GameMap:
    def __init__(s, mid, scale=1.0):
        s.id = mid; s.d = md = CFG["map_defs"][mid]; s.name = md.get("name", mid); s.pos = pos_of(mid)
        s.scale = scale * md.get("difficulty", 1); s.legend = lg = legend_of(md)
        rows = md.get("rows", []); fill = md.get("fill", ".")
        # Сохраняем реальные границы карты отдельно от общей буферной сетки.
        s.width = max((len(row) for row in rows if isinstance(row, str)), default=COLS)
        s.height = len(rows) if rows else ROWS
        s.width_px, s.height_px = s.width * T, s.height * T
        s.chars = [[rows[r][c] if r < len(rows) and c < len(rows[r]) else fill for c in range(COLS)] for r in range(ROWS)]
        s.info = [[lg.get(ch, {"type": "empty"}) for ch in row] for row in s.chars]
        s.visited = s.cleared = s.spawned = s.locked = False
        s.mobs, s.corpses, s.drops = [], [], []
        s.boss_spawned = False
        for c, r, e in s.cells():
            if "item" in e:
                wid = random_weapon() if e["item"] == "random" else e["item"]
                if wid in CFG["weapons"]: s.drops.append(Drop(c * T + T / 2, (r + 1) * T - 14, wid))
        s.exits = s.find_exits()
        s.lights = lighting.find_lights(s)   # блоки света: факелы, фонари, кристаллы, сферы
        s.containers = containers.create(s)   # ящики и сундуки карты (их клетки в физической сетке — стена, см. build)
        s.build()

    def cells(s):
        # Рисуем только реальные клетки этой карты, а не общую буферную сетку.
        for r in range(s.height):
            for c in range(s.width):
                yield c, r, s.info[r][c]

    def find(s, test):
        return [(c, r) for c, r, e in s.cells() if test(c, r, e)]

    def find_exits(s):
        """Выходы = связные группы одинаковых символов с полем exit."""
        seen, zones = set(), []
        for c, r, e in s.cells():
            if "exit" not in e or (c, r) in seen: continue
            ch = s.chars[r][c]; stack, group = [(c, r)], []
            seen.add((c, r))
            while stack:
                x, y = stack.pop(); group.append((x, y))
                for nx, ny in ((x + 1, y), (x - 1, y), (x, y + 1), (x, y - 1)):
                    if 0 <= nx < s.width and 0 <= ny < s.height and (nx, ny) not in seen and s.chars[ny][nx] == ch:
                        seen.add((nx, ny)); stack.append((nx, ny))
            zones.append(dict(char=ch, entry=e, cells=set(group), rect=box(group), ladder=e["type"] == "ladder"))
        return zones

    def build(s):
        """Физическая сетка (символы # = H x . D, их понимают игрок, мобы и пули) + картинка карты."""
        s.g = [[PHYS.get(e["type"], ".") for e in row] for row in s.info]
        if s.locked:
            for z in s.exits:
                for c, r in z["cells"]: s.g[r][c] = "D"
        containers.block(s)   # живые ящики не пропускают ни игрока, ни мобов, ни пули
        s.layer = s.render()

    # ---------- отрисовка ----------
    def render(s):
        # Фон и геометрия создаются в фактическом размере карты.
        # Раньше использовался общий размер MW × VH (максимум по всем картам),
        # поэтому фон на карте 60×32 растягивался на высоту 50 клеток и камера
        # показывала неверно обрезанный/размытый участок.
        surf = pg.Surface((s.width_px, s.height_px)); md = s.d
        surf.fill(tuple(opt(md, "bg_color", [20, 18, 30])))
        bg = md.get("background")
        if bg: draw_background(surf, bg, opt(md, "bg_mode", "cover"))
        dim = opt(md, "bg_dim", 0)
        if dim:
            sh = pg.Surface(surf.get_size(), pg.SRCALPHA); sh.fill((0, 0, 0, int(255 * dim))); surf.blit(sh, (0, 0))
        tiles = dict(CFG["maps"].get("tiles", {})); tiles.update(md.get("tiles", {}))
        s.draw_decor(surf, "back")   # мелкие детали «позади клеток»
        for c, r, e in s.cells():
            X, Y = c * T, r * T
            if s.g[r][c] == "D": draw_default(surf, "D", X, Y, None); continue
            # Все элементы окружения берутся из assets/environment. Если в легенде
            # задан sprite/tiles, он имеет приоритет; иначе выбираем вариант по координатам.
            spr = e.get("sprite") or tiles.get(e["type"])
            variants = {"wall": 3, "platform": 5, "ladder": 3, "spikes": 3}
            if not spr and e["type"] in variants:
                kind = e["type"]
                variant = (c * 7 + r * 11 + (c // 3) * 5) % variants[kind] + 1
                spr = f"environment/{kind}_{variant}.png" if kind != "spikes" else f"environment/spikes_{variant}.png"
            if spr:
                dw, dh = e.get("draw", [T, T]); ox, oy = e.get("offset", [0, 0])
                # Платформы и шипы занимают нижнюю часть клетки, сохраняя физику клетки.
                if not e.get("draw") and e["type"] == "platform": dw, dh = T, T
                img = sprite(spr, dw, dh, e.get("flip", False))
                if img: surf.blit(img, (X + ox, Y + T - dh + oy)); continue
            draw_default(surf, s.g[r][c], X, Y, e.get("color"))
        s.draw_decor(surf, "front")  # мелкие детали «поверх клеток»
        return surf

    def draw_decor(s, surf, z):
        """Мелкие детали карты (список "decor"): картинка, x/y — пиксели карты, w/h, flip. z: "back" — под клетками, иначе поверх."""
        for d in s.d.get("decor") or []:
            try:
                if (d.get("z") == "back") != (z == "back"): continue
                img = sprite(d["sprite"], int(d.get("w", T)), int(d.get("h", T)), bool(d.get("flip", False)))
                if img: surf.blit(img, (int(d["x"]), int(d["y"])))
            except (KeyError, TypeError, ValueError, AttributeError): continue

    # ---------- выходы и прибытие ----------
    def exit_at(s, x, y):
        c, r = int(x // T), int(y // T)
        for z in s.exits:
            if (c, r) in z["cells"]: return z
        return None

    def exit_touch(s, rect):
        return any(z["rect"].colliderect(rect) for z in s.exits)

    def exit_near(s, rect):
        for z in s.exits:
            if z["rect"].inflate(T * 2, T * 2).colliderect(rect): return z
        return None

    def arrival(s, came_from, via, camp):
        """Где появиться: (прямоугольник, на лестнице ли)."""
        if via and via.get("arrive"):
            # Символ прибытия может встречаться на карте несколько раз.
            # Нельзя объединять все такие клетки в один огромный прямоугольник:
            # выбираем отдельную связную группу, ближайшую к стороне входа.
            ch = via["arrive"]
            candidates, seen = [], set()
            for c, r, e in s.cells():
                if s.chars[r][c] != ch or (c, r) in seen:
                    continue
                stack, group = [(c, r)], []
                seen.add((c, r))
                while stack:
                    x, y = stack.pop(); group.append((x, y))
                    for nx, ny in ((x + 1, y), (x - 1, y), (x, y + 1), (x, y - 1)):
                        if (0 <= nx < s.width and 0 <= ny < s.height and
                                (nx, ny) not in seen and s.chars[ny][nx] == ch):
                            seen.add((nx, ny)); stack.append((nx, ny))
                candidates.append(group)
            if candidates:
                src_pos, dst_pos = pos_of(came_from), pos_of(s.id) if came_from else (None, None)
                edge = None
                if src_pos and dst_pos:
                    dx, dy = dst_pos[0] - src_pos[0], dst_pos[1] - src_pos[1]
                    if abs(dx) >= abs(dy) and dx: edge = "left" if dx > 0 else "right"
                    elif dy: edge = "top" if dy > 0 else "bottom"
                def arrival_score(group):
                    if edge == "left": return min(c for c, r in group) * 1000 + sum(r for c, r in group) / len(group)
                    if edge == "right": return (s.width - 1 - max(c for c, r in group)) * 1000 + sum(r for c, r in group) / len(group)
                    if edge == "top": return min(r for c, r in group) * 1000 + sum(c for c, r in group) / len(group)
                    if edge == "bottom": return (s.height - 1 - max(r for c, r in group)) * 1000 + sum(c for c, r in group) / len(group)
                    return min((c - s.width / 2) ** 2 + (r - s.height / 2) ** 2 for c, r in group)
                cells = min(candidates, key=arrival_score)
                return box(cells), any(s.info[r][c]["type"] == "ladder" for c, r in cells)
        if came_from:
            # Сначала используем явный обратный выход, если он задан в легенде.
            for z in s.exits:
                if camp.resolve(s.id, z["entry"]["exit"]) == came_from:
                    return z["rect"], z["ladder"]

            # Если на карте нет явного обратного выхода, определяем точку входа
            # по координатам карт в сетке мира. Это важно для карт с разным
            # размером: иначе игрок попадал в fallback-точку в центре уровня.
            src_pos, dst_pos = pos_of(came_from), pos_of(s.id)
            if src_pos and dst_pos:
                dx, dy = dst_pos[0] - src_pos[0], dst_pos[1] - src_pos[1]
                edge = None
                if abs(dx) >= abs(dy) and dx:
                    edge = "left" if dx > 0 else "right"
                elif dy:
                    edge = "top" if dy > 0 else "bottom"
                if edge:
                    if edge == "left": edge_cells = lambda c, r: c == 0
                    elif edge == "right": edge_cells = lambda c, r: c == s.width - 1
                    elif edge == "top": edge_cells = lambda c, r: r == 0
                    else: edge_cells = lambda c, r: r == s.height - 1
                    # Предпочитаем реальные выходы у нужного края.
                    edge_exits = [z for z in s.exits if any(edge_cells(c, r) for c, r in z["cells"])]
                    if edge_exits:
                        z = min(edge_exits, key=lambda z: min(
                            abs(c) + abs(r) if edge == "left" else
                            abs((s.width - 1) - c) + abs(r) if edge == "right" else
                            abs(r) + abs(c) if edge == "top" else
                            abs((s.height - 1) - r) + abs(c)
                            for c, r in z["cells"] if edge_cells(c, r)))
                        return z["rect"], z["ladder"]
                    # Если на краю нет помеченного выхода, всё равно появляемся
                    # у соответствующего края, а не в центре карты.
                    if edge == "left": c, r = 0, max(0, s.height - 3)
                    elif edge == "right": c, r = s.width - 1, max(0, s.height - 3)
                    elif edge == "top": c, r = max(0, s.width // 2), 0
                    else: c, r = max(0, s.width // 2), s.height - 1
                    return pg.Rect(c * T, r * T, T, T), False
        cells = s.find(lambda c, r, e: e.get("player"))
        if cells: c, r = cells[0]; return pg.Rect(c * T, r * T, T, T), s.info[r][c]["type"] == "ladder"
        return pg.Rect(s.width_px // 2 - T // 2, max(0, s.height_px - 2 * T), T, T), False

    # ---------- мобы ----------
    def spawn(s):
        s.spawned = True
        names = list(CFG["mobs"]); pool = s.d.get("mob_pool")
        if isinstance(pool, list): pool = {n: CFG["mobs"].get(n, {}).get("weight", 1) for n in pool}
        if not pool: pool = {n: CFG["mobs"][n].get("weight", 1) for n in names}
        pool = {n: w for n, w in pool.items() if n in CFG["mobs"]}
        for c, r, e in s.cells():
            if e.get("boss") and not s.boss_spawned:
                # B и C — два варианта маркера появления Моргарта; оба используют assets/boss/boss.json.
                boss = spawn_boss(s, s.scale, 1, (c * T + T / 2, (r + 1) * T))
                if boss:
                    s.mobs.append(boss)
                    s.boss_spawned = True
                continue
            kind = e.get("mob")
            if not kind: continue
            if kind == "random":
                if not pool: continue
                kind = random.choices(list(pool), list(pool.values()))[0]
            if kind not in CFG["mobs"]: continue
            d = CFG["mobs"][kind]
            s.mobs.append(Mob(kind, c * T + (T - d["w"]) / 2, r * T + T - d["h"], s.scale))
        if not s.mobs: s.cleared = True

    def base_cell(s, c, r):
        """Физика клетки без ящиков (то, что лежит в клетке по карте) — нужна, когда ящик сломан."""
        return PHYS.get(s.info[r][c]["type"], ".")

    def set_lock(s, on):
        if s.locked != on: s.locked = on; s.build()

    def spike_damage(s, c, r):
        return s.info[r][c].get("damage", 10) if 0 <= c < COLS and 0 <= r < ROWS else 10

def box(cells):
    xs = [c for c, _ in cells]; ys = [r for _, r in cells]
    return pg.Rect(min(xs) * T, min(ys) * T, (max(xs) - min(xs) + 1) * T, (max(ys) - min(ys) + 1) * T)

def draw_background(surf, path, mode):
    """mode: cover — растянуть с сохранением пропорций и обрезать (по умолчанию), stretch — растянуть как есть,
    fit — вписать целиком, center — как есть по центру, tile — замостить."""
    img = image(path)
    if not img: return
    iw, ih = img.get_size()
    sw, sh = surf.get_size()
    if mode == "stretch": surf.blit(sprite(path, sw, sh), (0, 0))
    elif mode == "tile":
        for y in range(0, sh, ih):
            for x in range(0, sw, iw): surf.blit(img, (x, y))
    elif mode == "center": surf.blit(img, ((sw - iw) // 2, (sh - ih) // 2))
    else:
        k = (max if mode != "fit" else min)(sw / iw, sh / ih); w, h = max(1, int(iw * k)), max(1, int(ih * k))
        surf.blit(sprite(path, w, h), ((sw - w) // 2, (sh - h) // 2))

def draw_default(v, ch, X, Y, color):
    col = tuple(color) if color else None
    if ch == "#": pg.draw.rect(v, col or (62, 56, 84), (X, Y, T, T)); pg.draw.rect(v, (88, 80, 114) if not col else [min(255, k + 26) for k in col], (X, Y, T, 4))
    elif ch == "D": pg.draw.rect(v, (160, 60, 70), (X, Y, T, T)); pg.draw.line(v, (90, 30, 40), (X, Y), (X + T, Y + T), 3)
    elif ch == "=": pg.draw.rect(v, col or (150, 120, 80), (X, Y, T, 8))
    elif ch == "H":
        for lx in (8, 24): pg.draw.line(v, col or (150, 110, 70), (X + lx, Y), (X + lx, Y + T), 3)
        for ly in (6, 22): pg.draw.line(v, col or (150, 110, 70), (X + 8, Y + ly), (X + 24, Y + ly), 2)
    elif ch == "x": pg.draw.polygon(v, col or (200, 200, 215), [(X + 2, Y + T), (X + 16, Y + T - 18), (X + 30, Y + T)])
    elif col: pg.draw.rect(v, col, (X, Y, T, T))

class Campaign:
    """Прохождение: какие карты уже созданы, откуда пришли, круг (после последней карты — заново и сложнее)."""
    def __init__(s, loop=0):
        s.loop = loop; s.maps = {}; s.came_from = {}
    @property
    def order(s): return order()
    @property
    def first(s):
        st = CFG["maps"].get("start")
        return st if st in CFG["map_defs"] else (s.order[0] if s.order else next(iter(CFG["map_defs"]), None))
    def scale(s): return 1 + CFG["maps"].get("loop_scale", .2) * s.loop
    def get(s, mid):
        if mid not in s.maps: s.maps[mid] = GameMap(mid, s.scale())
        return s.maps[mid]
    def resolve(s, cur, target):
        """Куда ведёт выход: id карты, END (конец) или None (некуда). Направления left/right/up/down и [x, y] — по сетке мира."""
        t = target_of(cur, target)
        return s.came_from.get(cur) if t == BACK else t
    def reload(s):
        """F5: карты пересобираются из файлов, зачищенные остаются зачищенными."""
        old = s.maps; s.maps = {}
        for mid, m in old.items():
            if mid not in CFG["map_defs"]: continue
            n = s.get(mid); n.visited = m.visited
            if m.cleared: n.cleared = n.spawned = True; n.drops = m.drops if m.spawned else n.drops

def check():
    """Проверка всех карт: список предупреждений (выводятся в консоль и на экран при запуске и F5)."""
    out, defs = list(CFG.get("map_errors", [])), CFG["map_defs"]
    seen = {}   # сетка мира: pos должен быть [x, y], в одной клетке — одна карта
    for mid, md in defs.items():
        if "pos" in md and pos_of(mid) is None: out.append(f"{mid}: pos должен быть [x, y] — два целых числа")
        p = pos_of(mid)
        if p and p in seen: out.append(f"{mid} и {seen[p]} стоят в одной клетке сетки {list(p)}")
        elif p: seen[p] = mid
    for mid in CFG["maps"].get("order", []):
        if mid not in defs: out.append(f"order: нет файла data/maps/{mid}.json")
    if not CFG["maps"].get("order"): out.append("maps.json: пустой order")
    for mid, md in defs.items():
        rows, lg = md.get("rows", []), legend_of(md)
        if not isinstance(rows, list) or not rows:
            out.append(f"{mid}: карта не содержит rows")
            rows = []
        widths = [len(row) for row in rows if isinstance(row, str)]
        if len(widths) != len(rows): out.append(f"{mid}: rows должны содержать только строки")
        if widths and min(widths) != max(widths):
            out.append(f"{mid}: строки карты имеют разную длину (будут дополнены пустыми клетками)")
        bad = sorted({ch for row in rows for ch in row if ch not in lg})
        if bad: out.append(f"{mid}: нет в легенде символов {' '.join(bad)} (будут пустотой)")
        for ch, e in lg.items():
            if e["type"] not in PHYS: out.append(f"{mid}: '{ch}' — неизвестный type {e['type']}")
            if e.get("mob") not in (None, "random") and e["mob"] not in CFG["mobs"]: out.append(f"{mid}: '{ch}' — нет моба {e['mob']}")
            if e.get("boss") and "__boss__" not in CFG.get("mobs", {}): out.append(f"{mid}: '{ch}' — не настроен босс (__boss__ в data/mobs.json)")
            if e.get("item") not in (None, "random") and e["item"] not in CFG["weapons"]: out.append(f"{mid}: '{ch}' — нет оружия {e['item']}")
            ex = e.get("exit")
            if ex is not None and not valid_exit(ex, defs): out.append(f"{mid}: '{ch}' ведёт на несуществующую карту {ex}")
            if e.get("light") is not None and not lighting.preset(e["light"]): out.append(f"{mid}: '{ch}' — нет света {e['light']} (см. lights в data/maps.json)")
            li = e.get("light")
            if isinstance(li, dict) and "color" in li and lighting.color_of(li["color"]) is None:
                out.append(f"{mid}: '{ch}' — непонятный цвет света {li['color']} (пример: \"красный\", \"green\", [255, 80, 40], \"#ff8040\")")
        for key in ("background",):
            if md.get(key) and not image(md[key]): out.append(f"{mid}: нет картинки assets/{md[key]}")
        for i, d in enumerate(md.get("decor") or []):
            if not isinstance(d, dict) or not d.get("sprite") or not all(isinstance(d.get(k), (int, float)) for k in ("x", "y")):
                out.append(f"{mid}: decor №{i + 1} — нужны sprite, x и y"); continue
            if not image(d["sprite"]): out.append(f"{mid}: decor №{i + 1} — нет картинки assets/{d['sprite']}")
    for mid in defs:   # переходы: ведут ли выходы куда надо и есть ли выход обратно
        for ch, ex in used_exits(mid):
            if not valid_exit(ex, defs): continue
            t = target_of(mid, ex)
            if t is None:
                if isinstance(ex, str) and ex in DIRS:
                    p = pos_of(mid)
                    out.append(f"{mid}: выход '{ch}' ({NAMES[ex]}) — " + ("у карты нет pos" if not p else f"в клетке {[p[0] + DIRS[ex][0], p[1] + DIRS[ex][1]]} нет карты"))
                elif isinstance(ex, (list, tuple)): out.append(f"{mid}: выход '{ch}' — в клетке {list(ex)} нет карты")
            elif t not in (END, BACK) and not any(target_of(t, e2) in (mid, BACK) for _, e2 in used_exits(t) if valid_exit(e2, defs)):
                out.append(f"{mid} → {t}: на карте {t} нет выхода обратно на {mid} (игрок появится у символа P)")
    return out

hunks:
def _mode_changed(self):
    if self.mode.get():
        self.ed.morg_mode.set(False)
        self.ed.status.set("Режим ящиков: ЛКМ — поставить ящик (по настройкам кисти) или выбрать, ПКМ — убрать.")
    self._refresh()

def _mode_changed(self):
    if self.mode.get():
        self.ed.morg_mode.set(False)
        dp = getattr(self.ed, "dpanel", None)
        if dp: dp.mode.set(False); dp.body.pack_forget(); dp.sel = None
        self.ed.status.set("Режим ящиков: ЛКМ — поставить ящик (по настройкам кисти) или выбрать, ПКМ — убрать.")
    self._refresh()

container_panel.py.full:
"""Панель «Ящики и сундуки» редактора карт (map_editor.py): расстановка и содержимое.

Включи «Режим ящиков» — и на карте:
  ЛКМ по пустой клетке  — поставить ящик с настройками «кисти» (тип, шанс появления, содержимое);
  ЛКМ по ящику          — выбрать его: панель покажет и позволит менять его настройки;
  ПКМ по ящику          — убрать.
Ящик ставится так, что нажатая клетка — его нижняя левая клетка (ящик 2×2 займёт эту клетку, клетку справа и две вверх).
Содержимое: пункты «предмет — шанс — сколько штук». Пока своего списка нет, ящик берёт содержимое типа из data/containers.json.
Результат пишется в карту, поле "containers" (формат — в containers.py).
"""
import copy
import json
import tkinter as tk
from tkinter import ttk, messagebox

RANDOM = "random_weapon"
MODES = [("independent", "каждый предмет бросает свой шанс"), ("pick_one", "выпадает не более одного предмета")]
MODE_LABEL = dict(MODES)
BLOCKING = ("wall", "ladder")            # такие клетки ящиком не занять
BLOCKING_MARKS = ("player", "exit", "boss")   # и клетки со стартом игрока, выходом, боссом

def hexc(rgb):
    try: return "#%02x%02x%02x" % tuple(max(0, min(255, int(v))) for v in rgb[:3])
    except (TypeError, ValueError): return "#aa7744"

def clean_loot(loot):
    """Список пунктов содержимого без мусора: у каждого item, chance 0..1, min >= 1, max >= min."""
    out = []
    for e in loot or []:
        if not isinstance(e, dict) or not e.get("item"): continue
        lo = max(1, int(e.get("min", 1))); hi = max(lo, int(e.get("max", lo)))
        item = {"item": str(e["item"]), "chance": round(max(0.0, min(1.0, float(e.get("chance", 1)))), 4)}
        if lo != 1 or hi != 1: item["min"], item["max"] = lo, hi
        out.append(item)
    return out

def clean_spec(spec):
    """Запись ящика для файла карты: только то, что отличается от умолчаний."""
    out = {"type": spec["type"], "x": int(spec["x"]), "y": int(spec["y"])}
    if spec.get("chance") is not None and float(spec["chance"]) < 1: out["chance"] = round(max(0.0, float(spec["chance"])), 4)
    if spec.get("hp") not in (None, ""): out["hp"] = float(spec["hp"]) if float(spec["hp"]) % 1 else int(spec["hp"])
    if spec.get("loot_mode") in MODE_LABEL: out["loot_mode"] = spec["loot_mode"]
    if spec.get("loot") is not None: out["loot"] = clean_loot(spec["loot"])
    return out


class ContainerPanel:
    def __init__(self, ed, parent, root, cell, palette):
        """ed — Editor; parent — куда положить панель; root — папка игры; cell — размер клетки в редакторе (px);
        palette — PALETTE редактора (символ, название, запись легенды): по ней определяем, куда ящик ставить нельзя."""
        self.ed, self.cell, self.root = ed, cell, root
        self.types, self.items = self._load_types(), self._load_items()
        self.sel = None                                  # индекс выбранного ящика в ed.containers или None (тогда правится «кисть»)
        first = next(iter(self.types), "")
        self.brush = {"type": first, "chance": 1.0, "loot_mode": None, "loot": None, "hp": None}
        self.blocked = {ch for ch, _, d in palette if d.get("type") in BLOCKING or any(k in d for k in BLOCKING_MARKS)}
        self.mode = tk.BooleanVar(value=False)
        self.type_var, self.chance_var, self.hp_var = tk.StringVar(), tk.StringVar(value="100"), tk.StringVar()
        self.lmode_var = tk.StringVar(value=MODES[0][1])
        self.item_var, self.pct_var, self.min_var, self.max_var = tk.StringVar(), tk.StringVar(value="50"), tk.StringVar(value="1"), tk.StringVar(value="1")
        self.title_var, self.info_var = tk.StringVar(), tk.StringVar()
        self._busy = False
        self._ui(parent)
        self._load_fields()

    # ---------- данные игры ----------
    def _read(self, rel):
        try: return json.loads((self.root / rel).read_text(encoding="utf-8"))
        except (OSError, ValueError): return {}

    def _load_types(self):
        d = self._read("data/containers.json").get("containers", {})
        return {tid: v for tid, v in d.items() if isinstance(v, dict)}

    def _load_items(self):
        """Предметы, которые можно положить в ящик: подпись -> id (оружие, предметы инвентаря, случайное оружие)."""
        out = {"Случайное оружие  [%s]" % RANDOM: RANDOM}
        for wid, w in sorted(self._read("data/weapons.json").items()):
            if isinstance(w, dict) and not wid.startswith("_"): out["%s  [%s]" % (w.get("name", wid), wid)] = wid
        for wid, it in sorted((self._read("assets/inventory.json").get("items") or {}).items()):
            if isinstance(it, dict) and wid not in {v for v in out.values()}: out["%s  [%s]" % (it.get("name", wid), wid)] = wid
        return out

    def type_label(self, tid): return "%s  [%s]" % (self.types.get(tid, {}).get("name", tid), tid)
    def type_from_label(self, label):
        label = label.strip(); return label[label.rindex("[") + 1:-1] if "[" in label and label.endswith("]") else label
    def item_label(self, wid): return next((k for k, v in self.items.items() if v == wid), wid)
    def item_from_label(self, label): return self.items.get(label.strip(), label.strip())
    def type_size(self, tid):
        d = self.types.get(tid, {}); return max(1, int(d.get("w", 1))), max(1, int(d.get("h", 1)))
    def default_loot(self, tid): return clean_loot(self.types.get(tid, {}).get("loot"))

    # ---------- интерфейс ----------
    def _ui(self, parent):
        box = ttk.LabelFrame(parent, text="Ящики и сундуки (расстановка и содержимое)", padding=5)
        box.pack(fill="x", pady=(8, 0)); self.box = box
        top = ttk.Frame(box); top.pack(fill="x")
        ttk.Checkbutton(top, text="Режим ящиков: ЛКМ — поставить / выбрать, ПКМ — убрать (клетки не рисуются)", variable=self.mode, command=self._mode_changed).pack(side="left")
        ttk.Label(top, textvariable=self.info_var, foreground="#555").pack(side="right")
        ttk.Label(box, textvariable=self.title_var, font=("Arial", 9, "bold")).pack(anchor="w", pady=(4, 2))
        row = ttk.Frame(box); row.pack(fill="x")
        ttk.Label(row, text="Тип:").pack(side="left")
        self.type_cb = ttk.Combobox(row, textvariable=self.type_var, state="readonly", width=26, values=[self.type_label(t) for t in self.types])
        self.type_cb.pack(side="left", padx=4); self.type_cb.bind("<<ComboboxSelected>>", lambda e: self._fields_changed())
        ttk.Label(row, text="Шанс появления, %:").pack(side="left", padx=(8, 0))
        ch = ttk.Spinbox(row, from_=0, to=100, increment=5, textvariable=self.chance_var, width=5, command=self._fields_changed); ch.pack(side="left", padx=4)
        ttk.Label(row, text="HP (пусто — как у типа):").pack(side="left", padx=(8, 0))
        hp = ttk.Entry(row, textvariable=self.hp_var, width=6); hp.pack(side="left", padx=4)
        for w in (ch, hp): w.bind("<FocusOut>", lambda e: self._fields_changed()); w.bind("<Return>", lambda e: self._fields_changed())
        row2 = ttk.Frame(box); row2.pack(fill="x", pady=(4, 0))
        ttk.Label(row2, text="Выпадение:").pack(side="left")
        self.lmode_cb = ttk.Combobox(row2, textvariable=self.lmode_var, state="readonly", width=38, values=[t for _, t in MODES])
        self.lmode_cb.pack(side="left", padx=4); self.lmode_cb.bind("<<ComboboxSelected>>", lambda e: self._fields_changed())
        ttk.Button(row2, text="Снять выбор (править кисть)", command=self.deselect).pack(side="right")
        body = ttk.Frame(box); body.pack(fill="x", pady=(6, 0))
        left = ttk.Frame(body); left.pack(side="left", fill="x", expand=True)
        self.tree = ttk.Treeview(left, columns=("item", "pct", "min", "max"), show="headings", height=4, selectmode="browse")
        for col, text, w in (("item", "Предмет", 230), ("pct", "Шанс %", 60), ("min", "От", 40), ("max", "До", 40)):
            self.tree.heading(col, text=text); self.tree.column(col, width=w, anchor="w" if col == "item" else "center")
        sb = ttk.Scrollbar(left, orient="vertical", command=self.tree.yview); self.tree.configure(yscrollcommand=sb.set)
        self.tree.pack(side="left", fill="x", expand=True); sb.pack(side="left", fill="y")
        self.tree.bind("<<TreeviewSelect>>", lambda e: self._row_selected())
        form = ttk.Frame(body); form.pack(side="left", padx=(10, 0), anchor="n")
        ttk.Label(form, text="Предмет:").grid(row=0, column=0, sticky="w")
        self.item_cb = ttk.Combobox(form, textvariable=self.item_var, width=34, values=list(self.items)); self.item_cb.grid(row=0, column=1, columnspan=4, sticky="we", padx=4)
        ttk.Label(form, text="Шанс, %:").grid(row=1, column=0, sticky="w", pady=2)
        ttk.Spinbox(form, from_=0, to=100, increment=5, textvariable=self.pct_var, width=5).grid(row=1, column=1, sticky="w", padx=4)
        ttk.Label(form, text="Штук от").grid(row=1, column=2, sticky="e"); ttk.Spinbox(form, from_=1, to=20, textvariable=self.min_var, width=3).grid(row=1, column=3, padx=2)
        ttk.Label(form, text="до").grid(row=1, column=4, sticky="e"); ttk.Spinbox(form, from_=1, to=20, textvariable=self.max_var, width=3).grid(row=1, column=5, padx=2)
        btns = ttk.Frame(form); btns.grid(row=2, column=0, columnspan=6, sticky="w", pady=(4, 0))
        ttk.Button(btns, text="Добавить", command=self.add_entry).pack(side="left")
        ttk.Button(btns, text="Заменить выбранный", command=self.replace_entry).pack(side="left", padx=4)
        ttk.Button(btns, text="Удалить", command=self.delete_entry).pack(side="left")
        ttk.Button(btns, text="Как у типа", command=self.reset_loot).pack(side="left", padx=4)
        ttk.Label(box, text="Шанс 100% — предмет выпадает всегда. «Один из»: шансы — доли от 100% (в сумме не больше 100). "
                            "Нет своего списка — ящик берёт содержимое типа из data/containers.json. Список предметов — оружие и вещи из assets/inventory.json -> items; можно вписать и свой id.",
                  wraplength=900, foreground="#555").pack(anchor="w", pady=(4, 0))

    # ---------- кисть / выбранный ящик ----------
    def active(self): return bool(self.mode.get())

    def _mode_changed(self):
        if self.mode.get():
            self.ed.morg_mode.set(False)
            dp = getattr(self.ed, "dpanel", None)
            if dp: dp.mode.set(False); dp.body.pack_forget(); dp.sel = None
            self.ed.status.set("Режим ящиков: ЛКМ — поставить ящик (по настройкам кисти) или выбрать, ПКМ — убрать.")
        self._refresh()

    def cur(self):
        """Настройки, которые сейчас правит панель: выбранный на карте ящик или кисть для новых."""
        if self.sel is not None and 0 <= self.sel < len(self.ed.containers): return self.ed.containers[self.sel]
        self.sel = None; return self.brush

    def deselect(self): self.sel = None; self._load_fields(); self._refresh()

    def _load_fields(self):
        """Показать настройки cur() в полях панели."""
        c = self.cur(); self._busy = True
        try:
            tid = c.get("type", ""); self.type_var.set(self.type_label(tid) if tid else "")
            self.chance_var.set(str(int(round(float(c.get("chance", 1.0)) * 100))))
            self.hp_var.set("" if c.get("hp") in (None, "") else str(c["hp"]))
            self.lmode_var.set(MODE_LABEL.get(c.get("loot_mode") or self.types.get(tid, {}).get("loot_mode", "independent"), MODES[0][1]))
        finally: self._busy = False
        self._fill_tree()
        if self.sel is None: self.title_var.set("Кисть: настройки для НОВЫХ ящиков. Выбери ящик на карте, чтобы править его самого.")
        else:
            c = self.ed.containers[self.sel]; self.title_var.set("Выбран ящик №%d: «%s», клетка (%d, %d)" % (self.sel + 1, self.types.get(c["type"], {}).get("name", c["type"]), c["x"], c["y"]))

    def _fields_changed(self):
        """Поля панели -> настройки кисти или выбранного ящика."""
        if self._busy: return
        c = self.cur(); tid = self.type_from_label(self.type_var.get())
        if tid in self.types:
            if tid != c.get("type"): c["type"] = tid; c["loot"] = None if self.sel is None else c.get("loot")
        try: c["chance"] = max(0.0, min(1.0, float(self.chance_var.get()) / 100))
        except ValueError: pass
        hp = self.hp_var.get().strip()
        try: c["hp"] = float(hp) if hp else None
        except ValueError: pass
        c["loot_mode"] = next((k for k, t in MODES if t == self.lmode_var.get()), None)
        if c["loot_mode"] == self.types.get(c.get("type"), {}).get("loot_mode", "independent") and c.get("loot") is None: c["loot_mode"] = None
        self._fill_tree(); self._refresh()

    # ---------- таблица содержимого ----------
    def effective_loot(self):
        c = self.cur(); return clean_loot(c["loot"]) if c.get("loot") is not None else self.default_loot(c.get("type"))

    def _fill_tree(self, select=None):
        self.tree.delete(*self.tree.get_children())
        for i, e in enumerate(self.effective_loot()):
            self.tree.insert("", "end", iid=str(i), values=(self.item_label(e["item"]), "%g" % round(e["chance"] * 100, 2), e.get("min", 1), e.get("max", e.get("min", 1))))
        own = self.cur().get("loot") is not None
        self.info_var.set(("своё содержимое" if own else "содержимое типа по умолчанию") + (" (пока пусто)" if not self.effective_loot() else ""))
        if select is not None and str(select) in self.tree.get_children(): self.tree.selection_set(str(select))

    def _row_selected(self):
        sel = self.tree.selection()
        if not sel: return
        e = self.effective_loot()[int(sel[0])]
        self.item_var.set(self.item_label(e["item"])); self.pct_var.set("%g" % round(e["chance"] * 100, 2)); self.min_var.set(str(e.get("min", 1))); self.max_var.set(str(e.get("max", e.get("min", 1))))

    def _entry_from_form(self):
        item = self.item_from_label(self.item_var.get())
        if not item: messagebox.showerror("Ящики", "Выбери предмет."); return None
        try:
            pct = float(self.pct_var.get().replace(",", ".")); lo = int(self.min_var.get()); hi = int(self.max_var.get())
        except ValueError: messagebox.showerror("Ящики", "Шанс и количество — числа."); return None
        if not 0 <= pct <= 100: messagebox.showerror("Ящики", "Шанс — от 0 до 100 %."); return None
        return {"item": item, "chance": pct / 100, "min": max(1, lo), "max": max(1, lo, hi)}

    def _own_loot(self):
        """Своё содержимое cur(): первая правка копирует содержимое типа, чтобы дальше менять его."""
        c = self.cur()
        if c.get("loot") is None: c["loot"] = copy.deepcopy(self.default_loot(c.get("type")))
        return c["loot"]

    def add_entry(self):
        e = self._entry_from_form()
        if e is None: return
        loot = self._own_loot(); loot.append(e); self._after_loot(len(loot) - 1)

    def replace_entry(self):
        sel = self.tree.selection(); e = self._entry_from_form()
        if not sel or e is None:
            if not sel: messagebox.showinfo("Ящики", "Выбери строку в таблице.")
            return
        loot = self._own_loot(); loot[int(sel[0])] = e; self._after_loot(int(sel[0]))

    def delete_entry(self):
        sel = self.tree.selection()
        if not sel: return
        loot = self._own_loot(); del loot[int(sel[0])]; self._after_loot(None)

    def reset_loot(self):
        self.cur()["loot"] = None; self._after_loot(None)

    def _after_loot(self, select):
        self._fill_tree(select); self._refresh()

    # ---------- карта ----------
    def cells_of(self, spec):
        w, h = self.type_size(spec["type"]); return [(spec["x"] + i, spec["y"] - j) for j in range(h) for i in range(w)]

    def at(self, x, y):
        for i, s in enumerate(self.ed.containers):
            if (x, y) in self.cells_of(s): return i
        return None

    def can_place(self, spec):
        """(можно, причина): ящик целиком на карте, не на стене/выходе/старте и не поверх другого ящика."""
        cells = self.cells_of(spec)
        for x, y in cells:
            if not (0 <= x < self.ed.map_w and 0 <= y < self.ed.map_h): return False, "ящик не помещается на карту"
            ch = self.ed.rows[y][x]
            if ch in self.blocked or ch in self._blocking_custom(): return False, "здесь стена, лестница, выход или старт"
            if self.at(x, y) is not None: return False, "здесь уже стоит ящик"
        return True, ""

    def _blocking_custom(self):
        leg = self.ed.meta.get("legend", {}) if isinstance(self.ed.meta, dict) else {}
        return {ch for ch, d in leg.items() if isinstance(d, dict) and (d.get("type") in BLOCKING or any(k in d for k in BLOCKING_MARKS))}

    def click(self, event):
        x, y = self.ed._cell_from_event(event)
        if not (0 <= x < self.ed.map_w and 0 <= y < self.ed.map_h): return
        i = self.at(x, y)
        if i is not None:
            self.sel = i; self._load_fields(); self._refresh()
            self.ed.status.set("Выбран ящик №%d. Меняй настройки в панели ниже; ПКМ — убрать." % (i + 1)); return
        tid = self.brush.get("type")
        if tid not in self.types: messagebox.showerror("Ящики", "Нет типов ящиков: проверь data/containers.json."); return
        spec = {"type": tid, "x": x, "y": y}
        for k in ("chance", "hp", "loot_mode"):
            if self.brush.get(k) is not None: spec[k] = self.brush[k]
        if self.brush.get("loot") is not None: spec["loot"] = copy.deepcopy(self.brush["loot"])
        ok, why = self.can_place(spec)
        if not ok: self.ed.status.set("Сюда ящик не поставить: " + why + "."); return
        self.ed.containers.append(spec); self._refresh()
        self.ed.status.set("Поставлен «%s» в клетку (%d, %d). Всего ящиков: %d." % (self.types[tid].get("name", tid), x, y, len(self.ed.containers)))

    def erase(self, event):
        x, y = self.ed._cell_from_event(event); i = self.at(x, y)
        if i is None: return
        del self.ed.containers[i]
        if self.sel is not None: self.sel = None if self.sel == i else (self.sel - 1 if self.sel > i else self.sel)
        self._load_fields(); self._refresh(); self.ed.status.set("Ящик убран. Осталось: %d." % len(self.ed.containers))

    def _refresh(self): self.ed._draw_all()

    def draw(self):
        """Ящики поверх сетки: цвет типа, подпись, шанс появления; выбранный — белая рамка."""
        cv, cs = self.ed.canvas, self.cell
        for i, s in enumerate(self.ed.containers):
            w, h = self.type_size(s["type"]); d = self.types.get(s["type"], {})
            x0, y0 = s["x"] * cs, (s["y"] - h + 1) * cs; x1, y1 = x0 + w * cs, y0 + h * cs
            cv.create_rectangle(x0 + 1, y0 + 1, x1 - 1, y1 - 1, fill=hexc(d.get("color", [170, 120, 60])), outline="#ffffff" if i == self.sel else "#3a2a18", width=3 if i == self.sel else 2, tags=("ct",))
            label = (d.get("name") or s["type"])[:1].upper()
            pct = int(round(float(s.get("chance", 1.0)) * 100))
            cv.create_text((x0 + x1) / 2, (y0 + y1) / 2, text=label if pct >= 100 else "%s %d%%" % (label, pct), fill="#1a1208", font=("Arial", 8 if pct < 100 else 10, "bold"), tags=("ct",))

    # ---------- сохранение / загрузка / правки карты ----------
    def load(self, containers):
        """Ящики из файла карты. Неизвестные типы остаются как есть (их просто не будет видно в игре)."""
        self.ed.containers = []
        for s in containers or []:
            if isinstance(s, dict) and "type" in s and "x" in s and "y" in s:
                try: spec = {"type": str(s["type"]), "x": int(s["x"]), "y": int(s["y"])}
                except (TypeError, ValueError): continue
                for k in ("chance", "hp", "loot_mode"):
                    if k in s: spec[k] = s[k]
                if isinstance(s.get("loot"), list): spec["loot"] = copy.deepcopy(s["loot"])
                self.ed.containers.append(spec)
        self.sel = None; self._load_fields()

    def dump(self):
        """Ящики для записи в карту (или пустой список)."""
        return [clean_spec(s) for s in self.ed.containers]

    def crop(self, w, h):
        """После изменения размера карты: убрать ящики, которые не помещаются."""
        keep = [s for s in self.ed.containers if all(0 <= x < w and 0 <= y < h for x, y in self.cells_of(s))]
        if len(keep) != len(self.ed.containers): self.ed.status.set("Убрано ящиков за краем карты: %d." % (len(self.ed.containers) - len(keep)))
        self.ed.containers = keep; self.sel = None; self._load_fields()

    def reset(self):
        self.ed.containers = []; self.sel = None; self._load_fields()
